// frontend/src/features/tickets/TicketCreate.jsx - Fixed & Improved Version
import React, { useState } from "react";
import api from "../../api/axios"; // Adjust path if needed
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux"; // To get auth token/user if required

const TicketCreate = () => {
  const [form, setForm] = useState({
    title: "",
    description: "",
    priority: "LOW",
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Optional: Get current user from Redux (if backend requires creator info)
  const user = useSelector((state) => state.auth.user);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const data = new FormData();
      data.append("title", form.title);
      data.append("description", form.description);
      data.append("priority", form.priority);
      if (file) data.append("attachment", file); // Match your backend field name (e.g., 'attachment' or 'file')

      // Optional: If backend expects creator or other fields
      // data.append("creator", user?.id); // If not auto-set by backend

      await api.post("/tickets/", data, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      // Success: Redirect to employee dashboard
      navigate("/employee");
    } catch (err) {
      console.error("Ticket creation error:", err);
      setError(
        err.response?.data?.detail ||
          err.response?.data?.message ||
          "Failed to create ticket. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5" style={{ maxWidth: "600px" }}>
      <h3 className="mb-4 text-center">Create New IT Ticket</h3>

      {error && (
        <div className="alert alert-danger mb-4" role="alert">
          {error}
        </div>
      )}

      <form onSubmit={handleSubmit}>
        <div className="mb-3">
          <label htmlFor="title" className="form-label">
            Title <span className="text-danger">*</span>
          </label>
          <input
            type="text"
            id="title"
            className="form-control"
            placeholder="Enter ticket title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="description" className="form-label">
            Description <span className="text-danger">*</span>
          </label>
          <textarea
            id="description"
            className="form-control"
            rows="5"
            placeholder="Describe the IT issue in detail..."
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="priority" className="form-label">
            Priority
          </label>
          <select
            id="priority"
            className="form-select"
            value={form.priority}
            onChange={(e) => setForm({ ...form, priority: e.target.value })}
          >
            <option value="LOW">Low</option>
            <option value="MEDIUM">Medium</option>
            <option value="HIGH">High</option>
          </select>
        </div>

        <div className="mb-4">
          <label htmlFor="file" className="form-label">
            Attach Evidence (Image/PDF)
          </label>
          <input
            type="file"
            id="file"
            className="form-control"
            accept="image/*,.pdf"
            onChange={(e) => setFile(e.target.files[0])}
          />
          <small className="form-text text-muted">
            Optional: Upload screenshot or error log (max 5MB recommended)
          </small>
        </div>

        <button
          type="submit"
          className="btn btn-primary w-100"
          disabled={loading || !form.title || !form.description}
        >
          {loading ? (
            <>
              <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
              Submitting...
            </>
          ) : (
            "Submit Ticket"
          )}
        </button>
      </form>
    </div>
  );
};

export default TicketCreate;
